export async function ci_jobs(context, params) {
    try {
        const jobs = await context.listJobs(params.runId, params);
        return JSON.stringify({
            total: jobs.total,
            page: jobs.page,
            perPage: jobs.perPage,
            jobs: jobs.items.map(j => ({
                id: j.id,
                name: j.name,
                status: j.status,
                conclusion: j.conclusion,
                url: j.url,
                createdAt: j.createdAt,
                startedAt: j.startedAt,
                completedAt: j.completedAt,
            })),
        });
    }
    catch (error) {
        return JSON.stringify({
            error: error instanceof Error ? error.message : 'Unknown error',
        });
    }
}
